css:
@import url('https://fonts.googleapis.com/css2?family=Roboto:ital,wght@0,100;0,300;0,400;0,500;0,700;0,900&display=swap');
@import url('https://fonts.googleapis.com/css2?family=Cairo:wght@200..1000&display=swap');

html, body {
    margin: 0;
    padding: 0;
    width: 100%;
    box-sizing: border-box;
}

.print-format{
    padding: 0;
}

.bootstrap.css {
    margin :0 0;
}

header {
    position : relative;
    margin: 0;
    padding: 0;
    width: 100vw; /* Ensures it uses the full viewport width */
    background-color :rgb(251, 252, 251);
    background-size: cover;
    box-sizing: border-box;
    height: 100px;
    border-radius: 5px;
}



.logo {
    position : absolute;
    width: 130px; 
    height: 105px;
    margin-right: 600px;
}

.site-name {
    display: block;
    position : absolute;
    font-weight: 700;
    font-size:30px;
    margin-right: 20px;
    margin-top: 30px;
    
}


table, th, td ,tr {
    color : black !important;
    margin: 40px ;
    padding: 8px;
    font-size: 20px;
    border:2px solid black ;
    text-align: center !important;
    font-size: 40px;
    font-weight: 700;
    
}
th {
        background-color:#4b9843;
        color : black;
        font-size: 40px;
        font-weight: 700 !important;
}
tr:nth-child(even){background-color: #f2f2f2}
@media print {
    table {
        width: 100%;  /* Make the table take the full width of the page */
        font-size: 40px; /* Adjust the font size if needed */
        margin: 20px 0px 20px 0px; /* Remove margin for better printing */
    }

    th, td {
        padding: 8px; /* Adjust padding for better spacing when printed */
    }
}

footer {
    margin: 0;
    padding: 0px;
    width: 100%; /* Ensure it takes full width */
    background-color: rgb(251, 252, 251);
    background-size: cover;
    box-sizing: border-box;
    height: 100px;
    border-radius: 5px;
    position: relative;
    margin-top: auto;
    
}
.footer-content {
    display: inline-block; 
    line-height: 40px; 
    text-align: center; 
    white-space: nowrap;
   
}
footer div {
    display: inline-block;
    margin: 10px 20px 10px 90px  !important; 
    font-size: 30px;
    line-height: normal; 
}

footer i {
    
    font-size: 40px; 
    color: green; 
}
